bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 - <<'PY'
import subprocess,json,sys
chat,topic=-1002373696859,1605
p=subprocess.run(["python3","scripts/userbot_topic_audit_client.py","--chat-id",str(chat),"--topic-id",str(topic)],capture_output=True,text=True,timeout=125)
if p.returncode:sys.exit(71)
line=next((s[len("USERBOT_TOPIC_AUDIT="):] for s in p.stdout.splitlines() if s.startswith("USERBOT_TOPIC_AUDIT={")),None)
if not line:sys.exit(72)
row=json.loads(line)["rows"][0]
ids=row.get("history_message_ids",[])
if row.get("topic_id")!=topic or len(ids)!=1 or row.get("button_types")!=["normal"]:sys.exit(73)
mid=ids[0]
if type(mid) is not int or mid<=0:sys.exit(74)
script="""import {readFileSync} from 'node:fs';
const f=process.env.BOT_TOKEN_FILE;
if(!f?.startsWith('/run/secrets/'))process.exit(31);
const token=readFileSync(f,'utf8').trim();
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(token))process.exit(32);
const target=JSON.parse(process.argv[1]);
const response=await fetch('https://api.telegram.org/bot'+token+'/pinChatMessage',{
 method:'POST',headers:{'Content-Type':'application/json'},
 body:JSON.stringify({chat_id:target.chat,message_id:target.message,disable_notification:true})
});
const body=await response.json();
if(body.ok!==true){console.error('TELEGRAM_PIN_API_REJECTED',body.error_code);process.exit(33);}
console.log('VIDEO_EXISTING_MESSAGE_PIN_REQUEST=PASS');
"""
r=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","--input-type=module","-e",script,json.dumps({"chat":chat,"message":mid})],capture_output=True,text=True,timeout=45)
if r.returncode:
 print("VIDEO_EXISTING_PIN_FAILED",r.returncode)
 sys.exit(75)
print("VIDEO_EXISTING_MESSAGE_PIN_API_PASS")
PY
